import zlib, base64, pathlib, os
_A = ""
_B = ""
_C = ""
_D = ""
_OUT = _A+_B+_C+_D
data = zlib.decompress(base64.b64decode(_OUT))
_out = pathlib.Path("../src/calibration.py")
_out.parent.mkdir(parents=True, exist_ok=True)
_out.write_bytes(data)
print(f"Written {len(data):,} bytes to {_out.resolve()}")